package com.quiz.servlet;
import com.quiz.dao.*; import com.quiz.model.*; import java.io.*; import java.sql.SQLException; import java.util.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/student/dashboard") public class StudentDashboardServlet extends HttpServlet { private final QuizDAO qd=new QuizDAO();private final ResultDAO rd=new ResultDAO();private final NotificationDAO nd=new NotificationDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");String subject=req.getParameter("subject");try{List<Quiz> quizzes=qd.findPublishedForStudent(u.getId(),subject);List<SubjectPerformance> performance=rd.findPerformanceByUser(u.getId());int completed=0,passed=0;double total=0;for(SubjectPerformance p:performance){completed+=p.getAttempts();passed+=p.getPassed();total+=p.getAverage()*p.getAttempts();}req.setAttribute("quizzes",quizzes);req.setAttribute("subjects",qd.findPublishedSubjects());req.setAttribute("selectedSubject",subject);req.setAttribute("notifications",nd.findPublished());req.setAttribute("performance",performance);req.setAttribute("completed",completed);req.setAttribute("available",quizzes.size());req.setAttribute("average",completed==0?"0.0":String.format("%.1f",total/completed));req.setAttribute("passed",passed);req.setAttribute("failed",completed-passed);req.getRequestDispatcher("/WEB-INF/views/student-dashboard.jsp").forward(req,resp);}catch(SQLException e){throw new ServletException("Could not load student dashboard",e);}}}
